import{H as e,V as t,et as n,j as r}from"./chunks/framework.BWKSSupd.js";var i=JSON.parse(`{"title":"Nuxt","description":"","frontmatter":{},"headers":[],"relativePath":"guide/essentials/nuxt.md","filePath":"guide/essentials/nuxt.md","lastUpdated":1785676849000}`),a={name:`guide/essentials/nuxt.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="nuxt" tabindex="-1">Nuxt <a class="header-anchor" href="#nuxt" aria-label="Permalink to “Nuxt”">​</a></h1><div class="warning custom-block"><p class="custom-block-title">v2 暂不支持 Nuxt</p><p>v1 通过 <code>$nuxt</code> 特判适配 Nuxt 2（<code>lib/util/RouteMatch.js</code> 中在 Nuxt 环境下优先从页面组件的 <code>meta</code> 选项读取页签配置）。v2 已移除该特判，对 Nuxt 3 的支持待评估。</p></div><h2 id="为什么移除" tabindex="-1">为什么移除 <a class="header-anchor" href="#为什么移除" aria-label="Permalink to “为什么移除”">​</a></h2><p>v1 的适配依赖两个 Nuxt 2 特有机制：</p><ol><li><strong>页面级 <code>meta</code> 选项</strong>：Nuxt 2 允许在页面组件上直接写 <code>meta</code>，v1 通过 <code>$nuxt.context.route.meta</code> 数组回溯读取。Nuxt 3 改用 <code>definePageMeta()</code>，机制完全不同。</li><li><strong><code>extendRoutes</code> 手动注入 iframe 路由</strong>：Nuxt 3 的路由由文件系统生成，扩展方式已变。</li></ol><p>v2 的页签配置统一走 <code>meta.routerTab</code>（见<a href="./">入门</a>），页面级动态信息走 <a href="./../advanced/dynamic-tab-info.html"><code>useRouterPage()</code></a>，两者都不再依赖框架特判。</p><h2 id="ssr-的限制" tabindex="-1">SSR 的限制 <a class="header-anchor" href="#ssr-的限制" aria-label="Permalink to “SSR 的限制”">​</a></h2><p>即使绕过上述配置差异，页签缓存本身与 SSR 存在冲突：</p><ul><li>缓存依赖 <code>KeepAlive</code> 与客户端组件实例的存活，服务端渲染阶段没有「页签历史」概念</li><li>页签恢复（<code>restore</code>）依赖 <code>sessionStorage</code>，服务端不可用</li><li>iframe 页签只能在客户端挂载</li></ul><p>因此即便未来适配 Nuxt 3，也只能以<strong>纯客户端插件</strong>方式运行（<code>ssr: false</code> 或包在 <code>&lt;ClientOnly&gt;</code> 内），这一路径尚未验证。</p><h2 id="替代方案" tabindex="-1">替代方案 <a class="header-anchor" href="#替代方案" aria-label="Permalink to “替代方案”">​</a></h2><p>需要 SSR 的项目，建议只在后台管理区（通常不需要 SEO 与首屏 SSR）使用页签，将该区域配置为客户端渲染。</p><p>如果你在 Nuxt 3 下成功接入，欢迎在 <a href="https://github.com/bhuh12/vue-router-tab/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 反馈实践方案。</p>`,13)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};